def _min_kernel(x_ref, out_ref):
    step = pl.program_id(1)
    block_min = jnp.min(x_ref[...], axis=1, keepdims=True)

    @pl.when(step == 0)
    def _initialize():
        out_ref[...] = block_min

    @pl.when(step != 0)
    def _accumulate():
        out_ref[...] = jnp.minimum(out_ref[...], block_min)


def workload(x):
    batch, reduction_size, width = x.shape
    reduction_steps = 4
    reduction_block = reduction_size // reduction_steps

    result = pl.pallas_call(
        _min_kernel,
        out_shape=jax.ShapeDtypeStruct((batch, 1, width), x.dtype),
        grid=(batch, reduction_steps),
        in_specs=[
            pl.BlockSpec(
                (1, reduction_block, width),
                lambda b, k: (b, k, 0),
            )
        ],
        out_specs=pl.BlockSpec(
            (1, 1, width),
            lambda b, k: (b, 0, 0),
        ),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "arbitrary")
        ),
    )(x)

    return result.reshape(batch, width)

